export interface BlogVisitorDto {
  id: string
  githubId: string
  login: string
  name?: string
  avatarUrl?: string
  status: "active" | "blocked"
}

export interface BlogCommentAuthor {
  id: string
  login: string
  name?: string
  avatarUrl?: string
}

export interface BlogComment {
  id: string
  postPath: string
  author: BlogCommentAuthor
  parentId?: string
  content: string
  status: "visible" | "deleted"
  likeCount: number
  createdAt: string
  replies?: BlogComment[]
}

export interface BlogPostStats {
  postPath: string
  viewCount: number
  likeCount: number
  commentCount: number
}

export interface BlogLikeInfo {
  targetId: string
  likeCount: number
  likedByMe: boolean
}

const TOKEN_KEY = "blog_visitor_token"

export function getApiBase(): string {
  return process.env.GATSBY_CONSOLE_API_BASE || "https://console.aimo.plus"
}

export function getToken(): string | null {
  if (typeof window === "undefined") return null
  return window.localStorage.getItem(TOKEN_KEY)
}

export function setToken(token: string | null): void {
  if (typeof window === "undefined") return
  if (token) window.localStorage.setItem(TOKEN_KEY, token)
  else window.localStorage.removeItem(TOKEN_KEY)
}

interface Envelope<T> {
  code: number
  msg: string
  data: T
}

async function request<T>(
  path: string,
  options: RequestInit = {},
  auth = false
): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(options.headers as Record<string, string>),
  }
  if (auth) {
    const token = getToken()
    if (token) headers.Authorization = `Bearer ${token}`
  }
  const resp = await fetch(`${getApiBase()}${path}`, { ...options, headers })
  const envelope = (await resp.json()) as Envelope<T>
  if (resp.status === 401 && auth) setToken(null)
  if (envelope.code !== 0) throw new Error(envelope.msg || "请求失败")
  return envelope.data
}

export const blogApi = {
  getMe: (): Promise<BlogVisitorDto> => request("/api/v1/blog/auth/me", {}, true),

  getComments: (postPath: string): Promise<BlogComment[]> =>
    request(`/api/v1/blog/comments?postPath=${encodeURIComponent(postPath)}`),

  postComment: (input: { postPath: string; content: string; parentId?: string }): Promise<BlogComment> =>
    request("/api/v1/blog/comments", { method: "POST", body: JSON.stringify(input) }, true),

  deleteComment: (id: string): Promise<{ id: string }> =>
    request(`/api/v1/blog/comments/${id}`, { method: "DELETE" }, true),

  toggleLike: (input: { targetType: "post" | "comment"; targetId: string }): Promise<{ liked: boolean; likeCount: number }> =>
    request("/api/v1/blog/likes", { method: "POST", body: JSON.stringify(input) }, true),

  getLikes: (targetType: "post" | "comment", targetIds: string[]): Promise<BlogLikeInfo[]> =>
    request(
      `/api/v1/blog/likes?targetType=${targetType}&targetIds=${targetIds.map(encodeURIComponent).join(",")}`,
      {},
      true
    ),

  reportView: (postPath: string): Promise<BlogPostStats> =>
    request("/api/v1/blog/stats/view", { method: "POST", body: JSON.stringify({ postPath }) }),
}
