import React, { useEffect, useState } from "react"
import { Eye, ChatCircle } from "@phosphor-icons/react"
import { blogApi } from "../comments/api"
import type { BlogPostStats, BlogLikeInfo } from "../comments/api"
import { LikeButton } from "../comments/LikeButton"

interface PostEngagementProps {
  postPath: string
  words: number
  paragraphs: number
}

export function PostEngagement({ postPath, words, paragraphs }: PostEngagementProps) {
  const [views, setViews] = useState<number | null>(null)
  const [commentCount, setCommentCount] = useState(0)
  const [likeCount, setLikeCount] = useState(0)
  const [liked, setLiked] = useState(false)
  const [loaded, setLoaded] = useState(false)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
    let cancelled = false

    const run = async () => {
      // 阅读数上报（简单 PV，每次加载 +1）并取回最新计数
      let stats: BlogPostStats | null = null
      try {
        stats = await blogApi.reportView(postPath)
      } catch {
        // 上报失败不影响点赞状态获取
      }
      // 「我是否已赞」（匿名按 IP+UA，登录按 visitor）
      let likeInfo: BlogLikeInfo | undefined
      try {
        const infos = await blogApi.getLikes("post", [postPath])
        likeInfo = infos[0]
      } catch {
        // 点赞状态获取失败时退回 reportView 的计数，liked 默认 false
      }
      if (cancelled) return
      // 同一批次更新（React 18 自动批处理），保证 LikeButton 首次挂载即拿到正确的 initial props
      // stats 失败不阻塞已取到的点赞状态
      setViews(stats?.viewCount ?? null)
      setCommentCount(stats?.commentCount ?? 0)
      setLikeCount(likeInfo?.likeCount ?? stats?.likeCount ?? 0)
      setLiked(likeInfo?.likedByMe ?? false)
      setLoaded(true)
    }
    void run()

    return () => {
      cancelled = true
    }
  }, [postPath])

  return (
    <div className="flex justify-between items-center text-xs text-foreground-muted mb-8">
      <span className="font-medium">
        共 {words} 字 · {paragraphs} 段落
      </span>
      {mounted && loaded && (
        <span className="flex items-center gap-4">
          <span className="inline-flex items-center gap-1">
            <Eye className="w-3.5 h-3.5 text-foreground-subtle" weight="duotone" />
            {views === null ? "…" : views}
          </span>
          <LikeButton targetType="post" targetId={postPath} initialCount={likeCount} initialLiked={liked} />
          <span className="inline-flex items-center gap-1">
            <ChatCircle className="w-3.5 h-3.5 text-foreground-subtle" weight="duotone" />
            {commentCount}
          </span>
        </span>
      )}
    </div>
  )
}
