import React, { useState } from "react"
import { Heart } from "@phosphor-icons/react"
import { blogApi } from "./api"

interface LikeButtonProps {
  targetType: "post" | "comment"
  targetId: string
  initialCount: number
  initialLiked: boolean
}

export function LikeButton({ targetType, targetId, initialCount, initialLiked }: LikeButtonProps) {
  const [count, setCount] = useState(initialCount)
  const [liked, setLiked] = useState(initialLiked)
  const [pending, setPending] = useState(false)

  const onClick = async () => {
    if (pending) return
    setPending(true)
    // optimistic
    setLiked(!liked)
    setCount(liked ? count - 1 : count + 1)
    try {
      const result = await blogApi.toggleLike({ targetType, targetId })
      setLiked(result.liked)
      setCount(result.likeCount)
    } catch {
      setLiked(liked)
      setCount(count)
    } finally {
      setPending(false)
    }
  }

  return (
    <button
      onClick={onClick}
      className={`inline-flex items-center gap-1 transition-colors duration-200 ${
        liked ? "text-accent" : "text-foreground-subtle hover:text-accent"
      }`}
      aria-label="点赞"
      aria-pressed={liked}
    >
      <Heart className="w-3.5 h-3.5" weight={liked ? "fill" : "duotone"} />
      <span className="text-xs">{count}</span>
    </button>
  )
}
